import{_ as e}from"./chunks/qr_ob1_debug.BFcqNe1b.js";import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,o as t,c as n,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const f=JSON.parse('{"title":"G7, ONE+","description":"","frontmatter":{"source_hash":"5d92e9e918","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/troubleshoot/g7.md","filePath":"it/troubleshoot/g7.md"}'),l={name:"it/troubleshoot/g7.md"};function s(c,i,u,p,d,m){return t(),n("div",null,[...i[0]||(i[0]=[r('<h1 id="g7-one-troubleshooting" tabindex="-1">Risoluzione problemi G7, ONE+ <a class="header-anchor" href="#g7-one-troubleshooting" aria-label="Permalink to &quot;Risoluzione problemi G7, ONE+ {#g7-one-troubleshooting}&quot;">​</a></h1><p>Se non l&#39;hai già fatto, vedi prima <a href="./../install/g7.html">come configurare G7/ONE+</a>. Molte delle cause descritte qui sotto sono le stesse di <a href="./g6.html">G6/ONE</a>: la potenza del segnale e la batteria sono trattate in quella pagina e collegate da qui invece di essere ripetute.</p><h2 id="step-by-step-troubleshooting" tabindex="-1">Risoluzione problemi passo passo <a class="header-anchor" href="#step-by-step-troubleshooting" aria-label="Permalink to &quot;Risoluzione problemi passo passo {#step-by-step-troubleshooting}&quot;">​</a></h2><p>Se xDrip è impostato per raccogliere i dati direttamente da un G7/ONE+ ma non riceve nulla, segui questi passaggi nell&#39;ordine:</p><ol><li>Disattiva la <a href="./../use/misc.html#engineering-mode">modalità Engineering</a>.</li><li>Disinstalla l&#39;app Dexcom o qualsiasi altra app che si collega direttamente al sensore.</li><li>Controlla il sensore stesso: vedi il filamento sporgere dalla parte superiore? Se sì, fotografalo per Dexcom: anche una volta connesso, il sensore non darà letture utili perché il filamento non è mai stato davvero inserito sotto la pelle, e te ne servirà uno nuovo.</li><li><strong>&quot;Missing QR Code&quot; nella pagina Dex Status</strong>: usa Impostazioni → Configurazione automatica per scansionare il codice QR della <a href="./../install/g7.html#setup-xdrip">guida di configurazione</a>, non un codice stampato sul sensore, poi tocca <strong>Riavvia Collector</strong> nella pagina Classic Status.</li><li><strong>&quot;Mismatch - wait&quot; nella pagina Dex Status</strong>: probabilmente hai inserito male il codice di associazione, oppure hai vecchi sensori usati nelle vicinanze. Allontana di più di 10 metri tutti i sensori usati in precedenza, ricontrolla il codice di associazione con quello stampato sull&#39;applicatore, poi tocca <strong>Riavvia Collector</strong>.</li><li><strong>Verifica la connettività</strong>: se non c&#39;è, usa uno <a href="./g6.html#how-strong-is-the-transmitter-signal">scanner Bluetooth</a> per controllare se il trasmettitore è almeno visibile, dopo aver allontanato i vecchi dispositivi. Se non è ancora visibile, tieni il magnete dell&#39;applicatore vicino al sensore per qualche secondo (può attivarlo), poi controlla di nuovo lo scanner e tocca <strong>Riavvia Collector</strong>.</li><li><strong>&quot;Deep Sleeping Errors&quot;, &quot;Checking Auth Errors&quot;, &quot;Scanning Errors&quot; o &quot;Initializing Errors&quot; nella pagina Dex Status</strong>: <ol><li>Annota l&#39;ID trasmettitore attuale a 4 cifre che trovi in Impostazioni.</li><li>Cambia la sua ultima cifra con un&#39;altra.</li><li>Disattiva la raccolta dati in xDrip e disattiva temporaneamente qualsiasi microinfusore, ricevitore o orologio collegato direttamente al sensore.</li><li>Attendi 15 minuti che il G7 entri in <a href="#g7-rapid-reconnect-mode">modalità di riconnessione rapida</a>.</li><li>Elimina tutti i dispositivi Bluetooth chiamati <code>DXCM*</code>, <code>DX01*</code>, <code>DX02*</code> o <code>DX04*</code> dall&#39;elenco dei dispositivi connessi/connessi in precedenza di Android.</li><li>Riattiva il collector Dex di xDrip (seleziona Dex come sorgente dati hardware) e ripristina l&#39;ID trasmettitore corretto che hai annotato.</li><li>Vai alla pagina Dex Status, attendi fino a un minuto una richiesta di associazione e approvala; se non compare, riavvia il telefono.</li><li>Una volta connesso con 3 letture consecutive, puoi riattivare microinfusore, ricevitore o orologio.</li></ol></li><li><strong>&quot;Sensor Failed 7&quot; nella pagina Dex Status</strong>: evita di sdraiarti sul sensore e rilassa l&#39;arto su cui si trova, bevi a sufficienza e aspetta fino a 3 ore che le letture tornino. Se le letture arrivano ma continuano a interrompersi a caso, vedi <a href="./g6.html#intermittent-connectivity">Connettività intermittente</a>.</li></ol><h2 id="g7-rapid-reconnect-mode" tabindex="-1">Modalità di riconnessione rapida del G7 <a class="header-anchor" href="#g7-rapid-reconnect-mode" aria-label="Permalink to &quot;Modalità di riconnessione rapida del G7 {#g7-rapid-reconnect-mode}&quot;">​</a></h2><p>In condizioni normali un G7/ONE+ trasmette una volta ogni 5 minuti, con ogni volta uno scambio di conferma bidirezionale. Se manca tre conferme di fila (15 minuti senza uno scambio riuscito), passa alla modalità di riconnessione rapida: ripete ogni lettura fino a 4 volte in più, una volta al minuto, così un&#39;app che si riconnette non deve aspettare un intero ciclo di 5 minuti per intercettarla. Questo continua per un massimo di 12 ore, o finché l&#39;app non si riconnette, a seconda di cosa avviene prima.</p><p>Non appena uno scambio riesce, le trasmissioni extra si fermano. xDrip legge l&#39;orario della lettura che riceve (che corrisponde comunque al ciclo di base di 5 minuti), quindi si risincronizza correttamente sul ritmo normale anche se ha intercettato una delle trasmissioni extra al minuto invece di quella &quot;vera&quot;.</p><h2 id="ob1-debugging-logs" tabindex="-1">Log di debug OB1 <a class="header-anchor" href="#ob1-debugging-logs" aria-label="Permalink to &quot;Log di debug OB1 {#ob1-debugging-logs}&quot;">​</a></h2><p>Vale allo stesso modo per G6, ONE, G7 e ONE+: usano tutti lo stesso collector OB1, che per impostazione predefinita registra pochissimi dettagli nei log. Se uno sviluppatore ti chiede log dettagliati durante la risoluzione di un problema di connessione, attiva prima il logging OB1 completo.</p><p>Il modo più semplice è scansionare questo codice QR con Impostazioni, <a href="./../use/copysettings.html#auto-configure">Configurazione automatica</a> e approvare la richiesta di importazione. Imposta una sola preferenza, Tag aggiuntivi per la registrazione.</p><p>Codice QR - Fai clic sull&#39;immagine per ingrandirla</p><p><a href="../../troubleshoot/images/qr_ob1_debug.png"><img src="'+e+'" style="zoom:50%;"></a></p><p>Puoi anche inserire i tag a mano:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a><br>   <a href="./../use/lesscommon.html#extra-logging-settings">Impostazioni di log supplementari</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Tag aggiuntivi per la registrazione</p><p> Ob1G5CollectionService:v,Ob1G5StateMachine:v</p></div><p>Poi:</p><ul><li>Aspetta che il problema si verifichi davvero prima di caricare i log. Attivare il logging da solo non registra ancora nulla di utile.</li><li>Apri il <a href="./../use/3dotsmenu.html#events-log">Log eventi</a> dal menu a 3 puntini, tocca Upload Logs e aggiungi una nota che identifichi il dispositivo, così potrà essere riconosciuto quando lo segnali.</li><li>Disattivalo dopo: svuota il campo Tag aggiuntivi per la registrazione e conferma. Altrimenti continua a generare un grande volume di log in più.</li></ul><h2 id="shared-with-g6one" tabindex="-1">In comune con G6/ONE <a class="header-anchor" href="#shared-with-g6one" aria-label="Permalink to &quot;In comune con G6/ONE {#shared-with-g6one}&quot;">​</a></h2><p>Questi punti valgono anche per i trasmettitori G7/ONE+: vedi la pagina <a href="./g6.html">Risoluzione problemi G6, ONE</a> per tutti i dettagli:</p><ul><li><a href="./g6.html#how-strong-is-the-transmitter-signal">Quanto è forte il segnale del trasmettitore?</a></li><li><a href="./g6.html#how-good-is-the-battery">Com&#39;è la batteria?</a></li><li><a href="./g6.html#transmitter-queue-stuck">Coda del trasmettitore bloccata</a></li></ul>',21)])])}const b=a(l,[["render",s]]);export{f as __pageData,b as default};
